class Solution {
public:
    int getMaxRepetitions(string s1, int n1, string s2, int n2) {
        int s1Count = 0, s2Count = 0, idx = 0;
        unordered_map<int, pair<int, int>> recall;

        while (s1Count < n1) {
            s1Count++;
            for (char ch : s1) {
                if (ch == s2[idx]) {
                    idx++;
                    if (idx == (int)s2.size()) {
                        s2Count++;
                        idx = 0;
                    }
                }
            }
            if (recall.count(idx)) {
                auto [prevS1, prevS2] = recall[idx];
                int periodS1 = s1Count - prevS1;
                int periodS2 = s2Count - prevS2;
                int cycles = (n1 - s1Count) / periodS1;
                s1Count += cycles * periodS1;
                s2Count += cycles * periodS2;
            } else {
                recall[idx] = {s1Count, s2Count};
            }
        }
        return s2Count / n2;
    }
};

class Solution {
    public int getMaxRepetitions(String s1, int n1, String s2, int n2) {
        int s1Count = 0, s2Count = 0, idx = 0;
        Map<Integer, int[]> recall = new HashMap<>();

        while (s1Count < n1) {
            s1Count++;
            for (int i = 0; i < s1.length(); i++) {
                if (s1.charAt(i) == s2.charAt(idx)) {
                    idx++;
                    if (idx == s2.length()) {
                        s2Count++;
                        idx = 0;
                    }
                }
            }
            if (recall.containsKey(idx)) {
                int[] prev = recall.get(idx);
                int periodS1 = s1Count - prev[0];
                int periodS2 = s2Count - prev[1];
                int cycles = (n1 - s1Count) / periodS1;
                s1Count += cycles * periodS1;
                s2Count += cycles * periodS2;
            } else {
                recall.put(idx, new int[]{s1Count, s2Count});
            }
        }
        return s2Count / n2;
    }
}

var getMaxRepetitions = function(s1, n1, s2, n2) {
    let s1Count = 0, s2Count = 0, idx = 0;
    const recall = new Map();

    while (s1Count < n1) {
        s1Count++;
        for (let i = 0; i < s1.length; i++) {
            if (s1[i] === s2[idx]) {
                idx++;
                if (idx === s2.length) {
                    s2Count++;
                    idx = 0;
                }
            }
        }
        if (recall.has(idx)) {
            const [prevS1, prevS2] = recall.get(idx);
            const periodS1 = s1Count - prevS1;
            const periodS2 = s2Count - prevS2;
            const cycles = Math.floor((n1 - s1Count) / periodS1);
            s1Count += cycles * periodS1;
            s2Count += cycles * periodS2;
        } else {
            recall.set(idx, [s1Count, s2Count]);
        }
    }
    return Math.floor(s2Count / n2);
};
